import{_ as e,a,c as i,ac as t}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"PostgreSQL 事务：MVCC、锁与幂等预留","description":"区分语句快照与事务快照，使用有条件UPDATE、唯一约束和SAVEPOINT保护并发与事务所有权。","frontmatter":{"title":"PostgreSQL 事务：MVCC、锁与幂等预留","description":"区分语句快照与事务快照，使用有条件UPDATE、唯一约束和SAVEPOINT保护并发与事务所有权。","showdocs":{"topics":[{"id":"postgres","title":"PostgreSQL","link":"/topics/postgres/"}],"kind":"知识专题","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"PostgreSQL 18 关系数据与事务实践","summary":"区分语句快照与事务快照，使用有条件UPDATE、唯一约束和SAVEPOINT保护并发与事务所有权。","status":"active","related":[{"title":"PostgreSQL 操作与命令","link":"/middleware/databases/postgres/plus/ecosystem/postgres-general-general","kind":"知识专题","scope":"general","audience":"general"},{"title":"PostgreSQL 完整项目：参数化库存预留 CLI","link":"/middleware/databases/postgres/plus/practice/application","kind":"应用实践","scope":"general","audience":"general"},{"title":"PostgreSQL 完整项目：参数化库存预留 CLI · 安装、初始化与运行至完整源码与参数绑定","link":"/middleware/databases/postgres/plus/practice/application-part-01","kind":"应用实践","scope":"general","audience":"general"},{"title":"PostgreSQL 完整项目：参数化库存预留 CLI · 完整测试、反例与执行计划至综合练习","link":"/middleware/databases/postgres/plus/practice/application-part-02","kind":"应用实践","scope":"general","audience":"general"},{"title":"PostgreSQL 建模、NULL、查询与执行计划","link":"/middleware/databases/postgres/base/intermediate/model","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"PostgreSQL 建模、NULL、查询与执行计划","link":"/middleware/databases/postgres/base/intermediate/model"},"next":{"text":"PostgreSQL 完整项目：参数化库存预留 CLI","link":"/middleware/databases/postgres/plus/practice/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"PostgreSQL 建模、NULL、查询与执行计划","link":"/middleware/databases/postgres/base/intermediate/model"},"next":{"text":"PostgreSQL 完整项目：参数化库存预留 CLI","link":"/middleware/databases/postgres/plus/practice/application"}},"headers":[],"relativePath":"middleware/databases/postgres/base/advanced/transactions.md","filePath":"middleware/databases/postgres/base/advanced/transactions.md"}'),n={name:"middleware/databases/postgres/base/advanced/transactions.md"};function r(l,s,p,o,d,k){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="postgresql-事务-mvcc、锁与幂等预留" tabindex="-1">PostgreSQL 事务：MVCC、锁与幂等预留 <a class="header-anchor" href="#postgresql-事务-mvcc、锁与幂等预留" aria-label="Permalink to &quot;PostgreSQL 事务：MVCC、锁与幂等预留&quot;">​</a></h1><blockquote><p>本轮仅做正文和源码静态审阅，以下命令、SQL、集成测试及恢复流程均未执行。过去真实运行记录保留在 <code>migration/knowledge-rebuild/m4-next/postgres/verification.md</code> 及其原始日志；历史结果不证明修改后的示例运行通过。</p></blockquote><h2 id="isolation" tabindex="-1">MVCC 与隔离级别 <a class="header-anchor" href="#isolation" aria-label="Permalink to &quot;MVCC 与隔离级别 {#isolation}&quot;">​</a></h2><p>前置：<a href="/middleware/databases/postgres/base/intermediate/model#schema">表约束</a>。事务是一组一起提交或回滚的操作；MVCC 使用多个行版本让读取者根据快照判断可见性，普通读通常不阻塞写，写写冲突仍会等待。MVCC 不是“不需要锁”，也不是“同一事务必定看到不变数据”。</p><p>默认 Read Committed 为每条语句取快照。事务A读库存5，B更新为4并提交，A下一条SELECT可读到4。Repeatable Read 在事务首条非事务控制语句建立快照，A两次普通SELECT仍读到5，事务结束后才能看新值。PostgreSQL 的 Read Uncommitted 等同 Read Committed；Repeatable Read 防止幻读，但仍可能有序列化异常。Serializable 用于要求结果等同某个串行顺序的场景，应用必须准备重试整个事务。<a href="https://www.postgresql.org/docs/18/transaction-iso.html" target="_blank" rel="noopener noreferrer">官方隔离说明</a></p><p>下面是分配到两个 psql 窗口的操作时间线，不能把整个代码块粘贴到同一窗口。先 verify 重置数据（book=3），两个窗口均连接 postgres_lab；B 必须处于默认自动提交状态。A 先 BEGIN 和第一次 SELECT，B 再 UPDATE，最后 A 第二次 SELECT。</p><div class="language-sql vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- A</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BEGIN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ISOLATION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> LEVEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> REPEATABLE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> READ</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sku</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;book&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- B（单独窗口，默认自动提交）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stock</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stock</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sku</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;book&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- A</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sku</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;book&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COMMIT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>A 的两次结果均为3，B 更新为4。A 提交后再执行 SELECT 得4。重新 verify 重置后将 A 改成 READ COMMITTED，第二次读为4。自动化测试用两个独立连接按这个时间线运行，不用 sleep 猜竞争先后。序列取号的增长不会随事务回滚，主键有空洞不等于数据丢失。</p><h2 id="locking" tabindex="-1">行锁、有条件 UPDATE 与超时 <a class="header-anchor" href="#locking" aria-label="Permalink to &quot;行锁、有条件 UPDATE 与超时 {#locking}&quot;">​</a></h2><p>“先 SELECT 库存，再用程序计算新库存 UPDATE”可能丢更新。使用单条 <code>UPDATE products SET stock=stock-%s WHERE sku=%s AND stock &gt;= %s RETURNING stock</code> 把判定和扣减放一起。并发更新同一行时等待前一事务，Read Committed 会对更新后的行重新检查 WHERE；库存不够时返回0行。返回0行是业务拒绝，不是连接失败。</p><p>需要先读后做多个决策时可用 <code>SELECT ... FOR UPDATE</code> 锁定目标行，并保持事务短小。所有事务按一致的商品顺序加锁有助减少死锁。历史测试中 A 持有book行锁，B设置 <code>SET lock_timeout=&#39;150ms&#39;</code> 后写同一行，真实得到 <code>55P03</code>。这个超时适合实验，生产值应根据业务时延选择。</p><p><code>40P01</code> 是死锁，<code>40001</code> 是序列化失败，可在应用边界有限次数、带退避地重试整个事务；不要仅重放事务中最后一条语句。<code>55P03</code> 要区分资源繁忙、NOWAIT或锁超时，先判断业务是否允许重试。不要在事务内等待用户输入、外部HTTP或长计算。</p><h2 id="idempotency" tabindex="-1">ON CONFLICT 与幂等参数 <a class="header-anchor" href="#idempotency" aria-label="Permalink to &quot;ON CONFLICT 与幂等参数 {#idempotency}&quot;">​</a></h2><p>幂等键通过 reservations.request_id 主键实现。<code>INSERT ... ON CONFLICT (request_id) DO NOTHING RETURNING request_id</code> 首次返回一行；重复键返回0行，再读原请求的 sku和quantity。相同参数返回 replayed=true，不再次扣库存；相同键换参数必须报错，不能把另一次购买误认为已处理。<a href="https://www.postgresql.org/docs/18/sql-insert.html" target="_blank" rel="noopener noreferrer">INSERT 官方文档</a></p><p>Read Committed 下并发唯一键冲突可能等待另一事务结果，本条 INSERT 看不到的提交可能在下一条SELECT看到。因此本实现依赖默认 Read Committed；调用者若改为 Repeatable Read/Serializable，必须接住序列化失败并从完整业务边界重试。测试规格要求8个同键请求只有1次扣减、7次重放；8个不同请求抢5件库存只有5次成功，最终库存0。历史测试有这两项结果；本轮给同键请求也增加屏障，便于同时起跑，但线程调度仍不能保证所有数据库语句在同一时刻发生。</p><p>先插入预留，再扣库存；若扣减失败，两者必须一起回滚。反例移除事务后，会留下pen的预留记录但没有成功扣库存，历史回滚测试真实报 <code>1 != 0</code> 并退出1。通过数据库约束替代不了多语句事务。</p><h2 id="ownership" tabindex="-1">事务所有权与 SAVEPOINT <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;事务所有权与 SAVEPOINT {#ownership}&quot;">​</a></h2><p>接收已有连接的库函数不能随意 <code>conn.rollback()</code>，否则会撤销调用者之前的修改。Psycopg <code>conn.transaction()</code> 在空闲连接开始事务，在调用者已开启事务时创建 SAVEPOINT；函数失败只回滚本次保存点，调用者可以捕获错误后继续。函数成功也不能替调用者提交外层事务。<a href="https://www.psycopg.org/psycopg3/docs/basic/transactions.html" target="_blank" rel="noopener noreferrer">Psycopg 事务管理</a></p><p>本项目使用 autocommit=True 避免普通查询悄悄留下长事务，reserve 显式开事务。测试先写note=&#39;caller&#39;，再让内部预留失败，捕获后 note仍在且外层可提交；另一个测试让内部预留成功后外层抛异常，确认库存和预留一起撤销。事务上下文的异常必须传播出当前保存点，再由外层捕获，不要在失败的SQL状态中继续查询。</p><p>练习：如果在 reserve 的 <code>conn.transaction()</code> 块内加入 <code>conn.commit()</code>，会怎样？提示：先区分“驱动拒绝破坏事务上下文”和“手动管理事务时越权提交”，再对照外层回滚测试的异常类型。解答见<a href="/middleware/databases/postgres/pro/review/review#answers">复习</a>。中文参考核对自<a href="https://github.com/postgres-cn/pgdoc-cn/blob/master/docs/18/mvcc.sgml" target="_blank" rel="noopener noreferrer">postgres-cn 文档翻译项目</a>，以本页链接的英文18手册为语义依据，翻译不作为本轮技术结论的唯一来源。</p>`,20)])])}const E=e(n,[["render",r]]);export{c as __pageData,E as default};
